<template>
  <div>

    <div class="btn-group mb-2">
      <button type="button" class="btn btn-success me-2" @click="handleStatus(3)" :disabled="isSubmitting">
        <span v-if="isSubmitting && status === 3" v-html="loadingSpinner()"></span>
        <span v-else>Approve</span>
      </button>

      <button type="button" class="btn btn-danger me-2" @click="handleStatus(4)" :disabled="isSubmitting">
        <span v-if="isSubmitting && status === 4" v-html="loadingSpinner()"></span>
        <span v-else>Reject</span>
      </button>

      <button type="button" class="btn btn-info me-2" @click="handleStatus(14)" :disabled="isSubmitting">
        <span v-if="isSubmitting && status === 14" v-html="loadingSpinner()"></span>
        <span v-else>Remark</span>
      </button>

      <button type="button" class="btn btn-warning" @click="handleStatus(17)" :disabled="isSubmitting">
        <span v-if="isSubmitting && status === 17" v-html="loadingSpinner()"></span>
        <span v-else>On Hold</span>
      </button>
    </div>

    <div v-if="status && block" class="mb-2 text-center">
      <span class="badge rounded-pill"
        :class="{
          'bg-danger': status == 4,
          'bg-success': status == 3,
          'bg-info': status == 14,
          'bg-warning': status == 17
        }"
        style="font-size: 1rem;"
      >
        {{
          status == 3
            ? 'Approve Request'
            : status == 4
              ? 'Reject Request'
              : status == 17
                ? 'Hold Request'
                : 'Fill Remark'
        }}
      </span>
    </div>

    <div class="input-group" v-if="status">
      <input
        type="text"
        class="form-control"
        :placeholder="status == 3 ? 'Enter Approval Remark' : status == 4 ? 'Enter Rejection Remark' : 'Enter Remark'"
        v-model="remark"
        v-if="block"
        :disabled="isSubmitting"
      >

      <button
        v-if="block"
        type="button"
        class="btn btn-primary me-2"
        :disabled="isSubmitting"
        @click="submit"
      >
        <span v-if="isSubmitting" v-html="loadingSpinner()"></span>
        <span v-else>Save</span>
      </button>
    </div>

  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

/* ✅ PROPS */
const props = defineProps({
  spinner: Boolean,
  loadingSpinner: Function,
  modelValue: Number,
  blockValue: Boolean,
  remarkValue: String,
  entryId: [String, Number]
})

/* ✅ EMITS (MUST BE FIRST) */
const emit = defineEmits([
  'update:blockValue',
  'update:modelValue',
  'update:remarkValue',
  'submit'
])

/* ✅ USER */
const user_id = Number(JSON.parse(localStorage.getItem("user"))?.id)

/* ✅ STATE */
const block = ref(props.blockValue || false)
const status = ref(props.modelValue || null)
const remark = ref(props.remarkValue || '')
const isSubmitting = ref(false)

/* ✅ WATCHERS */
watch(() => props.modelValue, val => status.value = val)
watch(() => props.remarkValue, val => remark.value = val)
watch(() => props.blockValue, val => block.value = val)
watch(() => props.spinner, val => isSubmitting.value = val)

watch(block, val => emit('update:blockValue', val))
watch(status, val => emit('update:modelValue', val))
watch(remark, val => emit('update:remarkValue', val))

/* ✅ ACTION */
const handleStatus = (newStatus) => {
  if (isSubmitting.value) return // Prevent clicking while submitting
  
  if (status.value === newStatus && block.value) {
    block.value = false
  } else {
    status.value = newStatus
    block.value = true
  }
}

/* ✅ STATUS MAPPING */
const getStatusName = (statusId) => {
  const statusMap = {
    3: 'approved',
    4: 'rejected',
    14: 'remarked',
    17: 'on_hold'
  }
  return statusMap[statusId] || 'unknown'
}

/* ✅ SUBMIT */
const submit = () => {
  if (isSubmitting.value) return // Prevent double submission
  
  isSubmitting.value = true
  
  const payload = {
    user_id,
    entry_id: props.entryId,
    status: status.value,
    status_name: getStatusName(status.value),
    remark: remark.value
  }

  emit('submit', payload)
}
</script>